# Check cluster 18 marker expression to understand cell type composition
import numpy as np

cluster18_cells = adata[adata.obs['leiden'] == '18']
print(f"Cluster 18 cells: {cluster18_cells.shape[0]}")

X = cluster18_cells.X.toarray() if hasattr(cluster18_cells.X, 'toarray') else cluster18_cells.X

# T-cell, NK, NKT, and APC markers
markers = {
    'T-cell': ['CD3D', 'CD3E', 'CD3G', 'CD247', 'TRAC', 'TRBC1', 'CD4', 'CD8A', 'CD8B'],
    'NK-cytotoxic': ['NCAM1', 'NKG7', 'GZMA', 'GZMB', 'GNLY', 'PRF1', 'KLRD1', 'KLRC1', 'KLRK1'],
    'NKT': ['ZBTB16', 'CD3D', 'CD3E', 'ZNF686', 'KLRG1', 'KLRB1'],
    'APC-like': ['CD1C', 'CD1A', 'CD1E', 'CD74', 'HLA-DRA', 'HLA-DRB1', 'CD80', 'CD86', 'CST3']
}

print("\nMarker expression in Cluster 18:")
for category, genes in markers.items():
    print(f"\n{category}:")
    for gene in genes:
        if gene in cluster18_cells.var_names:
            idx = list(cluster18_cells.var_names).index(gene)
            vals = X[:, idx]
            non_zero = vals[vals > 0]
            if len(non_zero) > 0:
                print(f"  {gene}: mean={np.mean(vals):.3f}, non-zero={len(non_zero)}/{len(vals)} ({100*len(non_zero)/len(vals):.1f}%)")
            else:
                print(f"  {gene}: all zeros")
        else:
            print(f"  {gene}: NOT FOUND")

# Check TF expression relevant to T-cell, NK, NKT, and APC programs in cluster 18
import numpy as np

cluster18_cells = adata[adata.obs['leiden'] == '18']
X = cluster18_cells.X.toarray() if hasattr(cluster18_cells.X, 'toarray') else cluster18_cells.X

# Relevant TFs for each program
tf_groups = {
    'T-cell': ['RUNX3', 'TBX21', 'FOXP3', 'BACH2', 'GATA3', 'TBX21', 'THPO'],
    'NK-cytotoxic': ['TCF7', 'TCF7L2', 'TCF3', 'GATA2', 'TOX', 'EOMES'],
    'NKT': ['ZBTB16', 'RORC', 'ROR1', 'GATA3', 'RUNX3'],
    'APC': ['SPI1', 'PU.1', 'IRF8', 'IRF4', 'BCL6', 'STAT1', 'STAT4', 'STAT6']
}

print("TF Expression in Cluster 18:")
all_tfs = []
for category, tfs in tf_groups.items():
    for tf in tfs:
        if tf not in all_tfs:
            all_tfs.append(tf)

for tf in all_tfs:
    if tf in cluster18_cells.var_names:
        idx = list(cluster18_cells.var_names).index(tf)
        vals = X[:, idx]
        print(f"{tf}: mean={np.mean(vals):.3f}, non-zero={np.sum(vals > 0)}/{len(vals)} ({100*np.sum(vals > 0)/len(vals):.1f}%)")
    else:
        print(f"{tf}: NOT FOUND")
